import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";

const tagVariants = cva(
	[
		"inline-flex items-center gap-[var(--gap-xs,0.25rem)] rounded-full border px-2.5 py-0.5 text-xs font-medium",
		"transition-all duration-[var(--duration-normal,200ms)] ease-out",
		"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
	].join(" "),
	{
		variants: {
			variant: {
				default: "border-transparent bg-primary text-primary-foreground",
				secondary:
					"border-foreground/15 bg-secondary text-secondary-foreground hover:border-foreground/20",
				destructive: "border-transparent bg-destructive text-destructive-foreground",
				outline: "border-foreground/20 text-foreground hover:border-foreground/30",
			},
		},
		defaultVariants: { variant: "default" },
	},
);

export interface TagProps
	extends Omit<React.HTMLAttributes<HTMLSpanElement>, "onRemove">,
		VariantProps<typeof tagVariants> {
	/** Forwarded ref onto the root span element. */
	ref?: React.Ref<HTMLSpanElement>;
	/** Optional leading icon (`<svg>` or component). Sized 12×12. */
	icon?: React.ReactNode;
	/**
	 * Click handler for the close button. When provided, an inline ✕ button
	 * is rendered after the children with an `aria-label` derived from the
	 * children's string content (or a generic "Remove" if no string can be
	 * extracted). Pass undefined for a non-interactive Tag — at that point,
	 * prefer Badge directly.
	 */
	onRemove?: () => void;
	/** Override the auto-derived `aria-label` on the close button. */
	removeLabel?: string;
}

/**
 * Walk a `React.ReactNode` tree depth-first and collect all string +
 * number leaves into a single space-separated label. Used to derive
 * the close button's `aria-label` even when children are JSX
 * (`<strong>Bold</strong>` → `"Bold"`).
 *
 * @param children - React children passed to `<Tag>`.
 * @returns Concatenated string content, or null if no string leaves found.
 */
function extractStringLabel(children: React.ReactNode): string | null {
	const parts: string[] = [];
	const visit = (node: React.ReactNode): void => {
		if (node === null || node === undefined || typeof node === "boolean") return;
		if (typeof node === "string") {
			parts.push(node);
			return;
		}
		if (typeof node === "number") {
			parts.push(String(node));
			return;
		}
		if (Array.isArray(node)) {
			for (const item of node) visit(item);
			return;
		}
		if (React.isValidElement(node)) {
			const props = node.props as { children?: React.ReactNode };
			visit(props.children);
		}
	};
	visit(children);
	const joined = parts.join(" ").replace(/\s+/g, " ").trim();
	return joined.length > 0 ? joined : null;
}

/**
 * An interactive tag / chip primitive — Badge with an optional dismiss
 * affordance. Mirrors {@link Badge}'s CVA variants so the visual sibling
 * is obvious; adds a built-in close button when `onRemove` is provided.
 *
 * For non-interactive labels (status indicators, counts) use {@link Badge}
 * directly. For "click to filter" state-bearing chips, use Toggle or
 * ToggleGroup — Tag is for "this token represents a value the user can
 * dismiss" (filters, multi-select selections, draft attachments).
 *
 * @example
 * ```tsx
 * <Tag variant="secondary" onRemove={() => removeFilter("urgent")}>
 *   Urgent
 * </Tag>
 * ```
 *
 * @returns A span containing the label + optional icon + optional close button.
 */
function Tag({
	className,
	variant,
	icon,
	onRemove,
	removeLabel,
	children,
	ref,
	...props
}: TagProps) {
	const labelText = extractStringLabel(children);
	const ariaLabel = removeLabel ?? (labelText ? `Remove ${labelText}` : "Remove");

	return (
		<span ref={ref} className={cn(tagVariants({ variant }), className)} {...props}>
			{icon ? (
				<span aria-hidden="true" className="-ml-0.5 [&_svg]:size-3 [&_svg]:shrink-0">
					{icon}
				</span>
			) : null}
			<span>{children}</span>
			{onRemove ? (
				<button
					type="button"
					onClick={onRemove}
					aria-label={ariaLabel}
					className={cn(
						"-mr-0.5 inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full",
						"transition-colors duration-[var(--duration-normal,200ms)] ease-out",
						"hover:bg-foreground/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1",
						"active:scale-[0.92]",
					)}
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						fill="none"
						stroke="currentColor"
						strokeWidth="2.5"
						strokeLinecap="round"
						strokeLinejoin="round"
						className="size-3"
						aria-hidden="true"
					>
						<line x1="18" y1="6" x2="6" y2="18" />
						<line x1="6" y1="6" x2="18" y2="18" />
					</svg>
				</button>
			) : null}
		</span>
	);
}

export { Tag, tagVariants };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
